import {BUSINESSES,answerBusiness,businessOffer,businessRoots} from './business.js?v=building-paint-1';
export function showBusiness(ui){const {city,dialog,close,setTool,save,clearUndo,notify,review}=ui,c=city();
 dialog('Business deals',`<p>Private operators pay the city while their facilities stand. Accepting a permit does not pay income until you choose a site. Construction is free, with one 3 × 3 building per deal.</p>${Object.entries(BUSINESSES).map(([type,d])=>{const b=businessOffer(c,type),placed=businessRoots(c).some(t=>t.type===type);return `<h3>${d.name} · §${d.stipend}/month</h3><p>${type==='casino'?'The casino increases nearby crime. Police coverage can reduce that effect.':'The plant adds strong local air and water pollution, reduces nearby land value, and can cause toxic clouds when random clouds are enabled. It does not dispose of your city’s municipal garbage.'}</p><p>${placed?'Placed and paying its monthly stipend.':b.accepted?'Permit accepted. Choose a clear, level site when ready.':b.offered!==null?'A proposal is ready for your decision.':`No proposal pending. Natural offers require ${type==='casino'?'128 residents and six':'256 residents and twelve'} elapsed months, with a negative monthly balance.${b.declinedUntil>c.month?' Another offer can arrive in '+(b.declinedUntil-c.month)+' months.':''}`}</p><div class="actions">${b.offered!==null&&!b.accepted?`<button data-business="${type}" data-answer="yes">Accept offer</button><button data-business="${type}" data-answer="no">Decline offer</button>`:''}${b.accepted&&!placed?`<button data-place-business="${type}" class="primary">Choose site</button>`:''}</div>`;}).join('')}<p>Demolition or disaster destruction stops the stipend. Accepted permits remain available for rebuilding. Scenarios may present offers earlier or offer a declined proposal again. Income and environmental effects use original economic tuning.</p><button id="businessFeedback">Give milestone 3 feedback</button>`);
 document.querySelectorAll('[data-business]').forEach(el=>el.onclick=()=>{const accept=el.dataset.answer==='yes',r=answerBusiness(c,accept,el.dataset.business);if(!r.ok)return notify(r.error);clearUndo();save();showBusiness(ui);notify(accept?'Offer accepted. Choose its site when ready.':'Offer declined.');});document.querySelectorAll('[data-place-business]').forEach(el=>el.onclick=()=>{setTool(el.dataset.placeBusiness);close();});document.getElementById('businessFeedback').onclick=()=>review(3);
}
